<?php require __DIR__.'/_layout.php';x1_require_role('admin');$db=x1_db();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){try{x1_check_csrf();if(!$db)throw new RuntimeException('SQLite required');$src=x1_db_path();if(!is_file($src))throw new RuntimeException('Database file missing');$name='x1-waveo-'.date('Ymd-His').'.sqlite';$dest=X1_ROOT.'/storage/backups/'.$name;if(!copy($src,$dest))throw new RuntimeException('Backup failed');$manifest=['format'=>'x1-waveo-backup','version'=>1,'createdAt'=>date('c'),'database'=>$name,'sha256'=>hash_file('sha256',$dest)];file_put_contents($dest.'.json',json_encode($manifest,JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES));x1_audit('backup_create',$name);$msg=$name;}catch(Throwable $e){$msg=$e->getMessage();}}$files=array_reverse(glob(X1_ROOT.'/storage/backups/*.sqlite')?:[]);top(tr('Backups','Backups'));?><section class="card hero"><div class=eyebrow>BACKUP / RECOVERY</div><h2><?=tr('Versioned SQLite backups with SHA-256 manifests','Backups SQLite versionados com manifest SHA-256')?></h2></section><?php if($msg):?><section class=notice><?=h($msg)?></section><?php endif?><section class=section><form method=post><input type=hidden name=csrf value="<?=x1_csrf()?>"><button><?=tr('Create backup now','Criar backup agora')?></button></form></section><section class=section><table><tr><th>File</th><th>Size</th><th>SHA-256</th></tr><?php foreach($files as $f):?><tr><td><?=h(basename($f))?></td><td><?=number_format(filesize($f))?></td><td><code><?=h(hash_file('sha256',$f))?></code></td></tr><?php endforeach?></table></section><?php bottom();